pub fn rle(input: &str) -> String {
    let mut out = String::new();
    let mut count = 0;
    for (i, c) in input.char_indices() {
        if i == 0 || c == input[i - 1] {
            count += 1;
        } else {
            out.push_str(&format!("{}{}", count, c));
            count = 1;
        }
    }
    if count > 0 {
        out.push_str(&format!("{}{}", count, c));
    }
    out
}

