pub fn caesar(s: &str, shift: u8) -> String {
    let shift = shift.abs() % 26;
    let lower = 'a';
    let upper = 'A';

    let mut out = String::new();
    for c in s.chars() {
        let ascii = c as u32;
        if ascii >= lower && ascii <= upper {
            let new_ascii = ((ascii - lower + shift) % 26 + lower) as u32;
            out.push((new_ascii - lower) as char);
        } else {
            out.push(c);
        }
    }
    out
}

