pub fn hex_to_rgb(s: &str) -> Option<(u8, u8, u8)> {
    if s.len() != 7 || s.chars().next().unwrap_or_default() != '#' {
        return None;
    }

    let (r, g, b) = s
        .chars()
        .skip(1)
        .map(|c| c.to_digit(16).ok_or(None))
        .collect::<Option<(u8, u8, u8)>>()
        .ok_or(None)?;

    if r.is_none() || g.is_none() || b.is_none() {
        return None;
    }

    Some((r.unwrap() as u8, g.unwrap() as u8, b.unwrap() as u8))
}

